practices.solutionCode:
WITH employees(id, department, salary) AS (
  VALUES (1, 'A', 8000), (2, 'A', 8000), (3, 'A', 6000),
         (4, 'B', 9000), (5, 'B', 7000), (6, 'C', 5000)
), ranked AS (
  SELECT id, department, salary,
    DENSE_RANK() OVER (PARTITION BY department ORDER BY salary DESC) AS salary_rank
  FROM employees WHERE salary IS NOT NULL
)
SELECT id, department, salary FROM ranked
WHERE salary_rank = 2 ORDER BY department, id;
